  "Private note": { zh: "私人笔记", ja: "個人メモ", fr: "Note privée", it: "Nota privata", es: "Nota privada" },
  "Your recipe box is empty.": { zh: "你的食谱收藏还是空的。", ja: "レシピボックスはまだ空です。", fr: "Votre boîte à recettes est vide.", it: "Il tuo ricettario è vuoto.", es: "Tu recetario está vacío." },
  "No recipes match this status yet.": { zh: "还没有符合这个状态的食谱。", ja: "この状態のレシピはまだありません。", fr: "Aucune recette n’a encore ce statut.", it: "Nessuna ricetta ha ancora questo stato.", es: "Aún no hay recetas con este estado." },
  "Save a recipe with the heart on Explore or on any recipe page.": { zh: "在“探索”或任意食谱页点击爱心即可保存食谱。", ja: "「探す」やレシピのページでハートを押すと保存できます。", fr: "Enregistrez une recette avec le cœur sur Explorer ou sur une page de recette.", it: "Salva una ricetta con il cuore in Esplora o in una pagina ricetta.", es: "Guarda una receta con el corazón en Explorar o en cualquier receta." },
  "Find a recipe": { zh: "查找食谱", ja: "レシピを探す", fr: "Trouver une recette", it: "Trova una ricetta", es: "Buscar una receta" },
  "Save this week": { zh: "保存本周计划", ja: "今週を保存", fr: "Enregistrer la semaine", it: "Salva la settimana", es: "Guardar la semana" },
  "Open prep list": { zh: "打开备菜清单", ja: "下準備リストを開く", fr: "Ouvrir la liste de préparation", it: "Apri la lista di preparazione", es: "Abrir la lista de preparación" },
  "Week saved. Ingredients and tools are ready in your prep list.": { zh: "已保存本周计划。食材和工具已在备菜清单中准备好。", ja: "今週を保存しました。材料と道具は下準備リストにそろっています。", fr: "Semaine enregistrée. Ingrédients et ustensiles sont prêts dans votre liste.", it: "Settimana salvata. Ingredienti e strumenti sono pronti nella lista.", es: "Semana guardada. Ingredientes y utensilios listos en tu lista." },
  "Choose a dish, then a meal": { zh: "先选菜，再选餐次", ja: "料理を選んでから食事を選ぶ", fr: "Choisissez un plat, puis un repas", it: "Scegli un piatto, poi un pasto", es: "Elige un plato y luego una comida" },
  "Drag a dish onto the week, or select it and choose a cell.": { zh: "把菜拖到周历上，或先选中再点击格子。", ja: "料理を週にドラッグするか、選んでからマスを選びます。", fr: "Glissez un plat sur la semaine, ou sélectionnez-le puis une case.", it: "Trascina un piatto sulla settimana, oppure selezionalo e scegli una casella.", es: "Arrastra un plato a la semana, o selecciónalo y elige una casilla." },
