  "{numA} of {numB} steps done": { zh: "已完成 {numA}/{numB} 步", ja: "{numB} 手順中 {numA} 完了", fr: "{numA} étapes sur {numB} faites", it: "{numA} passaggi su {numB} fatti", es: "{numA} de {numB} pasos hechos" },
